import re
from taf.ul.sc.generic_functionality import GenericFunctionality
from moler.util.moler_test import MolerTest
from moler.exceptions import CommandFailure


class UnixFunctionality(GenericFunctionality):
    """
    Generic UnixFunctionality class for other device class based on unix system.
    """

    def __init__(self, device_name=None, device=None, autoconnect=False, get_device=False):
        super(UnixFunctionality, self).__init__(device_name=device_name, device=device,
                                                autoconnect=autoconnect, get_device=get_device)
        self._system_type = None

    def wait_for_ping(self, destination, timeout=120):
        cmd_ping = self.device.get_cmd(cmd_name="ping", cmd_params={"destination": destination, "options": "-O"})
        event_ping = self.device.get_event(event_name="ping_response", event_params={"till_occurs_times": 1})
        event_ping.start()
        cmd_ping.start(timeout=timeout)
        if event_ping.await_done(timeout=timeout):
            self._cancel_ping(cmd_ping)
        MolerTest.info("{} is reachable".format(self.name))

    def get_uptime(self, from_file=False):
        uptime = None
        if from_file:
            cat_cmd = self.device.get_cmd(cmd_name="cat", cmd_params={'path': '/proc/uptime'})
            result = cat_cmd()
            match = re.search(r'(?P<SECONDS>^\d+)', result['LINES'][0])
            if match:
                uptime = match.group('SECONDS')
        else:
            uptime_cmd = self.device.get_cmd(cmd_name="uptime")
            uptime = uptime_cmd()

        return uptime

    def reboot(self, timeout=5):
        rebooter = self.device.get_cmd(cmd_name="reboot")
        rebooter(timeout=timeout)

    def remove_file(self, path, directory=False):
        """
        Remove file from path.

        :param path: path to file
        :param directory: If you want to remove whole directory, set this to True
        :return: nothing
        """
        if directory:
            flag = "-r"
        else:
            flag = ""
        cleaner = self.device.get_cmd(cmd_name="rm", cmd_params={'file': path, 'options': flag})
        cleaner()

    def make_directory(self, path):
        """
        Make directory.

        :param path: path to directory
        :return: nothing
        """
        maker = self.device.get_cmd(cmd_name="mkdir", cmd_params={'path': path, 'options': '-p'})
        maker()

    def move(self, source, destination):
        """
        Move files.

        :param source: source file/directory
        :param destination: destination file/directory
        :return: None
        """
        move_cmd = self.device.get_cmd(cmd_name="mv", cmd_params={'src': source, 'dst': destination})
        move_cmd()

    def change_directory(self, path):
        """
        Change working directory.

        :param path: path to directory
        :return: None
        """
        cd_cmd = self.device.get_cmd(cmd_name="cd", cmd_params={'path': path})
        cd_cmd()

    def ls(self, options):
        """
        List information about files/directory

        :param options: options of ls command
        :return: None
        """
        ls_cmd = self.device.get_cmd(cmd_name="ls", cmd_params={'options': options})
        ls_result = ls_cmd()

        return ls_result

    def zip(self, zip_file, source_files):
        """
        Zip files.

        :param zip_file: Zip file
        :param source_files: source files/directories
        :return: None
        """
        zip_cmd = self.device.get_cmd(cmd_name="zip", cmd_params={'zip_file': zip_file,
                                                                      'file_name': source_files,
                                                                      'options': "-rT"})
        zip_cmd()

    def get_file_content(self, path_to_file):
        """
        Get given file content.

        :param path_to_file: path to file
        :return: file content as a list of lines
        """
        cmd_cat = self.device.get_cmd(cmd_name="cat", cmd_params={"path": path_to_file,
                                                                  "options": ";echo ''"})
        cmd_result = cmd_cat()
        return cmd_result["LINES"]

    @staticmethod
    def _cancel_ping(ping_object):
        ping_object.cancel()

    def extract_grep_value(self, options, pattern):
        """
        Extract value from file with grep and regular expression pattern.

        :param options: Grep options
        :param pattern: Regular expression pattern
        :return: Extracted value
        """
        value = None

        cmd_grep = self.device.get_cmd(cmd_name="grep",
                                       cmd_params={"options": options})
        result = cmd_grep()

        if result["LINES"]:
            line = result['LINES'][0]
            if 'LINE' in line:
                line = line['LINE']
        search_obj = re.search(pattern, line)
        if search_obj:
            value = search_obj.group(1)

        return value

    _re_system_type = re.compile(r'^ID=\"?(?P<SYSTEM>\w+)')

    @property
    def system_type(self):
        if self._system_type is None:
            self._system_type = self.get_system_type()
        return self._system_type

    def get_system_type(self):
        cat_cmd = self.device.get_cmd(cmd_name="cat", cmd_params={"path": "/etc/*release"})
        cat = cat_cmd()
        for line in cat["LINES"]:
            search = re.search(self._re_system_type, line)
            if search:
                return search.group("SYSTEM").lower()

    def is_system_debian(self):
        if re.search('debian', self.system_type, re.IGNORECASE):
            return True
        else:
            return False

    def is_system_suse(self):
        if re.search('suse', self.system_type, re.IGNORECASE):
            return True
        else:
            return False

    def check_if_file_exists(self, file_path):
        """
        Check if file exist on the device.

        :param file_path: relative or absolute path to the file
        :return: True or False
        """

        file_exists = False
        try:
            self.ls(options=file_path)
            file_exists = True
        except CommandFailure:
            pass

        return file_exists

    def get_md5sum(self, path_to_file):
        """
        Get MD5 sum of file
        :param path_to_file: relative or absolute path to the file
        :return: md5sum
        """
        cmd_md5sum = self.device.get_cmd(cmd_name="md5sum", cmd_params={"path": path_to_file})
        cmd_result = cmd_md5sum()
        return cmd_result["SUM"]

    def get_pid_of_processes(self, process_name):
        """
        Get PID of processes
        :param process_name: command name to search
        :return: array with PIDs
        """
        cmd_ps = self.device.get_cmd(cmd_name="ps", cmd_params={"options": "-o pid,cmd -ae"})
        all_processes = cmd_ps()
        filtered_processes = [process['PID'] for process in all_processes if process_name in process['CMD']]
        return filtered_processes

    def run_script(self, script_cmd, additional_params=None):
        """
        Run script
        :param script_cmd: command to ran
        :param additional_params: params to run script
        :return: PID
        """
        cmd = script_cmd
        if additional_params is not None:
            cmd = " ".join([script_cmd, additional_params])

        run_script = self.device.get_cmd(cmd_name="run_script",
                                         cmd_params={"script_command": cmd})
        run_script()
        pid = self.get_pid_of_processes(script_cmd)
        return pid

    def kill_process(self, processes, options="-9"):
        """
        Run script
        :param processes: Array with PID of processes
        :param options: Additional options to kill command
        :return: None
        """

        for process in processes:
            kill = self.device.get_cmd(cmd_name="kill",
                                       cmd_params={"pid": str(process), "options": options})
            kill()

    def copy_file(self, source, destination):
        """
        Copy file
        :param source: Path to source file
        :param destination: Path to destination directory
        :return: None
        """
        cmd_cp = self.device.get_cmd(cmd_name="cp", cmd_params={"options": "-r", "src": source, "dst": destination})
        cmd_cp()

    def create_symbolic_link(self, link_path, target_path):
        cmd_symbolic_link = self.device.get_cmd(
            cmd_name="ln", cmd_params={
                "options": "-s {} {}".format(target_path, link_path)
            }
        )
        cmd_symbolic_link()

